// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Size} from "../src/Size.sol";

contract InvMutTest is Test {
    Size c;

    function setUp() public {
        c = new Size();
    }

    function testFuzz_property(bytes32 role, address account) public {
        // Domain: any role, any account. In the freshly deployed contract nobody
        // holds any role, so `renounceRole` for one's own address must succeed
        // as a no-op in the reference. The mutant reverts exactly then.
        vm.prank(account);
        bool ok;
        try c.renounceRole(role, account) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a call to renounceRole confirming the caller's own
        // account always succeeds (it is a no-op when the role is absent).
        assertTrue(ok && !c.hasRole(role, account));
    }
}
